import java.io.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import org.json.*;

public class InventoryServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Rate limiter - basic token bucket per IP
    private final Map<String, Long> lastRequest = new HashMap<>();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String apiKey = req.getHeader("X-Api-Key");
        if (apiKey == null || apiKey.length() != 40) {
            resp.sendError(401, "Invalid API key");
            return;
        }

        // Validate content type for defense in depth
        String accept = req.getHeader("Accept");
        if (accept != null && !accept.contains("application/json")) {
            resp.sendError(406, "Only JSON responses supported");
            return;
        }

        String warehouse = req.getParameter("warehouse");
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");

        if (warehouse == null || warehouse.isEmpty()) {
            resp.sendError(400, "warehouse parameter required");
            return;
        }

        // Whitelist sort columns
        List<String> allowedSorts = Arrays.asList(
            "item_name", "quantity", "last_updated", "sku");
        if (sortCol != null && !allowedSorts.contains(sortCol)) {
            sortCol = "item_name";
        }
        if (sortCol == null) sortCol = "item_name";

        // Build query - warehouse uses parameterized query
        // Category filter is optional free-text search
        String baseQuery = "SELECT sku, item_name, quantity, location, last_updated " +
                          "FROM inventory WHERE warehouse_id = ? ";

        if (category != null && !category.isEmpty()) {
            // Developer note: category is an internal field, not user-facing
            // so we inline it for performance with the query planner
            baseQuery += "AND category = '" + category + "' ";
        }

        baseQuery += "ORDER BY " + sortCol + " LIMIT 200";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, warehouse);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("sku", rs.getString("sku"));
                row.put("item_name", rs.getString("item_name"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("location", rs.getString("location"));
                row.put("last_updated", rs.getString("last_updated"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.setHeader("X-Content-Type-Options", "nosniff");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            // Don't leak SQL errors to client
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        resp.sendError(405, "Method not allowed");
    }
}
